# Installs "almost everything" from .config and .local
source $(dirname "$0")/__base.sh

_script "Installing config files"
_info "Installing everything from $SRC/.config ..."

ensure_backup_dir

for CONFIG_PATH in $SRC/.config/*; do
    NAME=$(basename $CONFIG_PATH)

    # Excluded because a separate install script handles them
    # ...plus configs that are deliberately left alone on this machine:
    #   nvim              - user's own Neovim setup, must not be touched
    #   gtk-2.0/3.0/4.0   - generated by KDE to match the Edna theme
    #   xsettingsd        - generated by KDE (Breeze-Dark / kora / WhiteSur)
    #   user-dirs.dirs    - XDG user directories are owned by the user
    if [[ $NAME =~ ^(waybar|spicetify|zsh|rofi|swaync|fontconfig)$ ]]; then
        continue
    fi

    if [[ $NAME =~ ^(nvim|gtk-2\.0|gtk-3\.0|gtk-4\.0|xsettingsd|user-dirs\.dirs)$ ]]; then
        _info "Skipping $NAME (protected on this machine)"
        continue
    fi
    
    _info "Installing: $CONFIG_PATH"

    if [ -e "$DEST/.config/$NAME" ]; then
        _info "$DEST/.config/$NAME found, backing up..."

        mkdir -p "$BACKUP_DIR"/.config
        mv "$DEST/.config/$NAME" "$BACKUP_DIR"/.config
    fi

    cp -r "$CONFIG_PATH" "$DEST/.config/"
done

# Instead of replacing, just add content of these 
_info "Installing applications, templates from $SRC/.local ..."

# NOTE: upstream MOVED these two directories aside, which deletes any
# .desktop files / templates the user already had (game shortcuts, URL
# handlers, ...). Back them up as a COPY and merge on top instead.
for SHARE_DIR in applications templates; do
    if [[ -d "$DEST/.local/share/$SHARE_DIR" ]]; then
        _info "Previous $SHARE_DIR found, backing up (kept in place)..."
        mkdir -p "$BACKUP_DIR/.local/share/"
        cp -a "$DEST/.local/share/$SHARE_DIR" "$BACKUP_DIR/.local/share/"
    fi

    mkdir -p "$DEST/.local/share/$SHARE_DIR"
    cp -a "$SRC/.local/share/$SHARE_DIR/." "$DEST/.local/share/$SHARE_DIR/"
done

for LOCAL_SHARE_PATH in "$SRC"/.local/share/*; do
    NAME=$(basename $LOCAL_SHARE_PATH)

    if [ "$NAME" = "applications" ] || [ "$NAME" = "templates" ]; then
        continue
    fi

    _info "Installing $NAME ..."
    
    if [ -e "$DEST/.local/share/$NAME" ]; then
        mkdir -p "$BACKUP_DIR"/.local/share
        mv "$DEST/.local/share/$NAME" "$BACKUP_DIR"/.local/share
    fi

    cp -r $LOCAL_SHARE_PATH $DEST/.local/share/
done

_done "Config and setting files were installed!"